use c6_core::{core_player::{self,initialization as init},core_stream::{ThroughFirstPlayer,ThroughPlayerManager,ThroughPlayerManagerError},map,unit,player_tail};
use sha2::{Digest,Sha256};
use std::sync::Arc;
use std::cell::Cell;
use std::io::{Read,Write};
fn main(){
 let mode=std::env::args().nth(1).unwrap();
 if mode=="tail"{std::io::stdout().write_all(&player_tail::Tail::default().encode(player_tail::Context{player_version:47,was_ever_alive:false},unit::Limits::default()).unwrap()).unwrap();return;}
 let mut input=vec![];std::io::stdin().read_to_end(&mut input).unwrap();
 let binding=init::WireBinding{role:init::WireRole::ReadInputCore,core_sha256:Sha256::digest(&input).into(),occurrence_id:b"independent-source-case-only".to_vec(),output_id:None,inputs:init::InputIdentities{configuration_sha256:[1;32],rules_inputs_sha256:[2;32],database:init::DatabaseIdentity::LiveSnapshotUnavailable,dlc_inputs_sha256:[3;32],mods_inputs_sha256:[4;32],content_inputs_sha256:[5;32]}};
 let calls=Cell::new(0usize);
 let provider=|id:init::PlayerIdentity| -> Option<Arc<init::InitializationSnapshot>> {calls.set(calls.get()+1);assert_eq!(id.manager_index,0);None};
 let shared=map::Limits{max_items:16_000_000,..map::Limits::default()};let player=unit::Limits{max_items:16_000_000,..unit::Limits::default()};
 let mut wrong=binding.clone();wrong.core_sha256[0]^=1;
 assert!(matches!(ThroughPlayerManager::decode(&input,shared,player,wrong,&provider),Err(ThroughPlayerManagerError::SourceImageMismatch{..})));assert_eq!(calls.get(),0);
 let mut tail_changed=input.clone();*tail_changed.last_mut().unwrap()^=1;
 assert!(matches!(ThroughPlayerManager::decode(&tail_changed,shared,player,binding.clone(),&provider),Err(ThroughPlayerManagerError::SourceImageMismatch{..})));assert_eq!(calls.get(),0);
 if mode=="native-refusal"{
  let standard=ThroughFirstPlayer::decode(&input,shared,player).unwrap();assert_eq!(standard.consumed,6583893);assert_eq!(standard.player_prefix.boundary,core_player::Boundary::AIMilitary);
  let(encoded,items)=standard.player_prefix.encode_prefix_with_items(player).unwrap();assert_eq!(encoded,input[standard.core.consumed..standard.consumed]);assert_eq!(items,250396);
  for _ in 0..2{assert!(matches!(ThroughPlayerManager::decode(&input,shared,player,binding.clone(),&provider),Err(ThroughPlayerManagerError::Player(core_player::Error::MissingInitializationSnapshot(_)))));}
  assert_eq!(calls.get(),2);println!("native_refused {} {}",standard.consumed,calls.get());return;
 }
 if mode=="synthetic-global-43"{
  use c6_core::core_stream::ThroughGlobalAi;
  let value=ThroughGlobalAi::decode(&input,shared,player,binding.clone(),&provider).unwrap();assert_eq!(calls.get(),0);assert!(value.players.player_prefix.complete_player_manager_wire());assert_eq!(value.players.player_prefix.players().count(),43);
  let(wire,global_items)=value.global_ai.encode_with_items(player).unwrap();assert_eq!(wire,input[value.players.consumed..value.consumed]);assert_eq!(wire.len(),368461);assert_eq!(global_items,47501);assert_eq!(value.items_used,value.players.items_used+global_items);assert_eq!(value.tail,&[91,92,93]);assert!(std::ptr::eq(value.tail.as_ptr(),input[value.consumed..].as_ptr()));
  let exact_shared=map::Limits{max_bytes:value.consumed,max_items:value.items_used,max_allocation:value.players.core.logical_allocation_used,..shared};let exact_post=unit::Limits{max_bytes:value.consumed-value.players.core.map_end,max_items:value.items_used-value.players.core.items_used};
  assert!(ThroughGlobalAi::decode(&input,exact_shared,exact_post,binding.clone(),&provider).is_ok());
  for short in [map::Limits{max_bytes:exact_shared.max_bytes-1,..exact_shared},map::Limits{max_items:exact_shared.max_items-1,..exact_shared}]{assert!(ThroughGlobalAi::decode(&input,short,exact_post,binding.clone(),&provider).is_err());}
  for short in [unit::Limits{max_bytes:exact_post.max_bytes-1,..exact_post},unit::Limits{max_items:exact_post.max_items-1,..exact_post}]{assert!(ThroughGlobalAi::decode(&input,exact_shared,short,binding.clone(),&provider).is_err());}
  assert_eq!(calls.get(),0);println!("source_global_43 {} {} {}",value.players.consumed,value.consumed,value.items_used);return;
 }
 assert_eq!(mode,"synthetic-false-43");
 let value=ThroughPlayerManager::decode(&input,shared,player,binding.clone(),&provider).unwrap();assert_eq!(calls.get(),0);
 assert_eq!(value.player_prefix.player_count,43);assert_eq!(value.player_prefix.players().count(),43);assert_eq!(value.player_prefix.unfinished_player_entries,0);assert!(value.player_prefix.complete_player_manager_wire());assert!(!value.player_prefix.initialization_reconstructed());assert_eq!(value.player_prefix.initialization_basis(),core_player::InitializationBasis::ContextFreeWire);
 for(index,p)in value.player_prefix.players().enumerate(){assert_eq!(p.requested_owner,index as i32);assert_eq!(p.header.owner,index as i32);assert!(!p.header.saved_was_ever_alive());assert!(p.initialization_snapshot.is_none());assert!(p.ai_military.is_none());assert!(p.tail.as_ref().unwrap().alive.is_none());}
 assert_eq!(value.tail,&input[value.consumed..]);assert!(std::ptr::eq(value.tail.as_ptr(),input[value.consumed..].as_ptr()));assert_eq!(value.tail,&[91,92,93]);
 let (encoded,post_items)=value.player_prefix.encode_prefix_with_items(player).unwrap();assert_eq!(encoded,input[value.core.consumed..value.consumed]);assert_eq!(value.items_used,value.core.items_used+post_items);
 let exact_shared=map::Limits{max_bytes:value.consumed,max_items:value.items_used,max_allocation:value.core.logical_allocation_used,..shared};let exact_player=unit::Limits{max_bytes:encoded.len(),max_items:post_items};
 assert!(ThroughPlayerManager::decode(&input,exact_shared,exact_player,binding.clone(),&provider).unwrap().player_prefix.complete_player_manager_wire());
 for short in [map::Limits{max_bytes:exact_shared.max_bytes-1,..exact_shared},map::Limits{max_items:exact_shared.max_items-1,..exact_shared}]{assert!(ThroughPlayerManager::decode(&input,short,exact_player,binding.clone(),&provider).is_err());}
 for short in [unit::Limits{max_bytes:exact_player.max_bytes-1,..exact_player},unit::Limits{max_items:exact_player.max_items-1,..exact_player}]{assert!(ThroughPlayerManager::decode(&input,exact_shared,short,binding.clone(),&provider).is_err());assert!(value.player_prefix.encode_prefix_with_items(short).is_err());}
 assert_eq!(value.player_prefix.encode_prefix_with_items(exact_player).unwrap(),(encoded,post_items));
 assert!(ThroughPlayerManager::decode(&input,shared,player,binding,&provider).unwrap().player_prefix.complete_player_manager_wire());assert_eq!(calls.get(),0);
 println!("source_false_43 {} {} {} {}",value.consumed,value.items_used,post_items,std::mem::size_of::<core_player::FirstPlayer>());
}
